from html import escape as e
import json
CITIES=[('bengaluru','Bengaluru, Karnataka'),('delhi','Delhi'),('mumbai','Mumbai, Maharashtra'),('pune','Pune, Maharashtra'),('chennai','Chennai, Tamil Nadu'),('hyderabad','Hyderabad, Telangana'),('jaipur','Jaipur, Rajasthan'),('ahmedabad','Ahmedabad, Gujarat'),('kolkata','Kolkata, West Bengal'),('lucknow','Lucknow, Uttar Pradesh')]
def number(name,label,value,min=0,max=100000000,step='any'):
 return f'<label>{label}<input type="number" name="{name}" value="{value}" min="{min}" max="{max}" step="{step}" required></label>'
def subsidy(v):
 if v['type']=='car':title='No private-car purchase subsidy under PM E-DRIVE';desc='Private electric cars are outside this central purchase-incentive scheme. State benefits are separate and depend on location and conditions.'
 elif v['type']=='three-wheeler':title='Not currently eligible under the checked L5 scheme';desc='PM E-DRIVE incentives for new L5 registrations closed on 26 December 2025. Low-speed e-rickshaws are a different scheme category; state support needs separate verification.'
 else:title='Subsidy eligibility needs verification';desc='PM E-DRIVE e-two-wheeler support runs to 31 March 2028, subject to approved model, advanced battery, ₹1.5 lakh ex-factory ceiling, registration, e-voucher and available funds. Current cap: lower of ₹2,500/kWh, ₹5,000 or 15% of ex-factory price. A listing price alone cannot establish eligibility.'
 return '<div class="subsidy-status"><strong>'+title+'</strong><p>'+desc+'</p><p class="location-benefit">Select your city below to see the road-tax position.</p><a href="https://pmedrive.heavyindustries.gov.in/" target="_self">Official scheme · checked 14 Oct 2026 ↗</a></div>'
def road_widget(v=None):
 is_model=v is not None
 v=v or {'type':'car','priceMin':1200000,'variants':[],'priceNote':'Enter the ex-showroom quote for the exact vehicle and battery ownership plan.'}
 vs=[x for x in v.get('variants',[]) if x.get('price')]
 variant=('<label>Choose variant price<select name="variant"><option value="">Starting price / custom quote</option>'+''.join(f'<option value="{x["price"]}">{e(x["name"])} · ₹{x["price"]:,}</option>' for x in vs)+'</select></label>') if vs else ''
 types={'car':'Electric car (private)','scooter':'Electric scooter','motorcycle':'Electric motorcycle','three-wheeler':'Electric auto (L5 commercial)'}
 return '<section class="road-calculator" id="price"><h2>Estimate your on-road cost</h2><p class="micro">Select your Indian registration city. Rules checked 14 October 2026. This is an estimate, not a dealer quote.</p><form class="road-form" data-type="'+v['type']+'"><div class="input-grid"><label>Registration city<select name="city">'+''.join('<option value="'+k+'">'+label+'</option>' for k,label in CITIES)+'</select></label><label>Vehicle category<select name="type">'+''.join('<option value="'+k+'"'+(' selected' if k==v['type'] else '')+'>'+label+'</option>' for k,label in types.items() if not is_model or k==v['type'])+'</select></label>'+variant+number('price','Ex-showroom price (₹)',v.get('priceMin') or 0,1)+number('insurance','Insurance quote (₹)',0)+'</div><p class="micro">'+e(v.get('priceNote',''))+'</p><p class="micro">Insurance starts at ₹0 because a reliable premium depends on the vehicle, cover and owner. ₹0 means <b>not included</b>, not free. Enter an insurer/dealer quote. No subsidy is deducted again.</p><details><summary>Have a confirmed road-tax quote?</summary><label>Replace the calculated road tax including cess (₹)<input type="number" name="override" min="0" max="100000000" step="any" placeholder="Leave blank to use city rules"></label><p class="micro">This override resets when you change city, category, variant or price.</p></details><div class="road-result" aria-live="polite"></div></form></section>'
def running_widget():
 fields=[('km','Distance each month (km)',1000,0,100000),('eff','Petrol vehicle mileage (km/litre)',15,1,100),('petrol','Petrol price (₹/litre)',100,1,500),('cons','EV consumption (kWh/100 km)',15,0.1,150),('tariff','Charging price (₹/unit)',8,0,100),('loss','Charging losses (%)',10,0,50)]
 return '<section class="section" id="running-cost"><span class="eyebrow">EVERYDAY ELECTRIC</span><h2 class="section-title">What could you save on running costs?</h2><p>Compare energy costs using your own travel and charging pattern.</p><div class="calculator"><form id="ev-running-form"><label>Example vehicle<select id="ev-running-type"><option value="car">Car</option><option value="scooter">Scooter / motorcycle</option><option value="auto">Auto-rickshaw (petrol comparison)</option></select></label><div class="input-grid">'+''.join(number(*x) for x in fields)+'</div></form><div id="ev-running-result" class="calc-result" aria-live="polite"></div></div><p class="micro">Running costs only: excludes purchase cost, loans, maintenance, insurance, battery rental and resale value. The auto example compares petrol, not CNG or diesel.</p></section>'
def solar_widget():
 fields=[('roof','Usable, unshaded roof (sq ft)',200,1,100000),('kw','System capacity (kW)',2,.1,100),('units','Home electricity use (units/month)',240,0,100000),('tariff','Electricity price (₹/unit)',8,0,100),('cost','Installed quote before subsidy (₹)',130000,0,10000000)]
 advanced=[('sun','Equivalent full-sun hours/day',5,1,8),('performance','Output after system losses (%)',80,1,100),('self','Solar generation used directly at home (%)',50,0,100),('exportRate','Confirmed export credit (₹/unit)',0,0,100),('maintenance','Annual cleaning / maintenance allowance (₹)',1300,0,100000)]
 return '<section id="solar-calculator" class="section"><span class="eyebrow">YOUR HOME. YOUR NUMBERS.</span><h2 class="section-title">See what your roof could save.</h2><p>Choose a household example, then adjust it to your bill and usable roof. Every amount is an estimate.</p><div class="house-presets" aria-label="Household examples">'+''.join('<button type="button" data-house="'+str(i)+'" aria-pressed="'+str(i==1).lower()+'">'+n+'<small>'+str(k)+' kW example</small></button>' for i,(n,k) in enumerate([('Small House',1),('Medium House',2),('Large House',3),('Villa',5)]))+'</div><div class="calculator"><form id="solar-form"><div class="input-grid">'+''.join(number(*x) for x in fields)+'</div><details><summary>Customise sunlight, daytime use and costs</summary><div class="input-grid">'+''.join(number(*x) for x in advanced)+'</div><p class="micro">Export credit defaults to zero. Use your DISCOM’s confirmed rate and settlement method; a bill credit is not necessarily cash income.</p></details><label class="check-label"><input type="checkbox" name="eligible"> Show potential PM Surya Ghar support for an eligible new residential system</label><label class="check-label"><input type="checkbox" name="special"> Special-category central rate applies to my location</label><p class="micro">Support remains conditional on approval, compliant domestic cells/modules, registered vendor and commissioning. Existing-system expansion needs a separate eligibility check. State top-ups are not included.</p></form><div id="solar-result" class="calc-result" aria-live="polite"></div></div><p class="micro">Planning defaults: 100 sq ft/kW, 5 equivalent full-sun hours × 80% performance, 50% direct use, ₹65,000/kW installed and 1% annual maintenance allowance. The tariff and usage are examples, not your city’s tariff. No battery is included.</p></section>'
